with long_format as (select id, supplier_id, measure, metric_value from (select id, supplier_id, cost, price from products) src unpivot (metric_value for measure in (cost, price))) select case when metric_value >= 65 then 'LARGE' else 'SMALL' end as metric_value_tier, sort_array(collect_set(measure)) as measure_list, count(case when measure = 'cost' then 1 end) as cost_count, round(avg(metric_value), 2) as avg_metric_value, count(distinct supplier_id) as distinct_supplier_ids from long_format group by case when metric_value >= 65 then 'LARGE' else 'SMALL' end;
